export const SAFE=Object.freeze({x:120,y:160,width:840,height:1280}),CONTENT=Object.freeze({x:0,y:0,width:1080,height:1920}),HUD=Object.freeze({left:144,right:936,eyebrow:202,title:266,stage:312,caption:1412,bar:1436}),WATERMARK_RESERVE=Object.freeze([]);export function scaledSafe(s){const e=s/1080;return{x:SAFE.x*e,y:SAFE.y*e,width:SAFE.width*e,height:SAFE.height*e}}export function shadowKey(s,e){return e.time<s.lead+s.buildDuration+.48?String(e.time):`${e.placed}/${e.removed}`}export function sceneCorners(s){const e=new Map;for(const o of[...s.base,...s.blocks,...s.excavation]){const c=`${Math.floor(o.x/3)},${Math.floor(o.z/3)}`,i=["x","y","z"].map((r,t)=>o[r]-o[["sx","sy","sz"][t]]/2-1.5),n=["x","y","z"].map((r,t)=>o[r]+o[["sx","sy","sz"][t]]/2+1.5);if(!e.has(c))e.set(c,{lo:i,hi:n});else{const r=e.get(c);for(let t=0;t<3;t++)r.lo[t]=Math.min(r.lo[t],i[t]),r.hi[t]=Math.max(r.hi[t],n[t])}}return[...e.values()].flatMap(({lo:o,hi:c})=>[0,1].flatMap(i=>[0,1].flatMap(n=>[0,1].map(r=>({x:[o[0],c[0]][i],y:[o[1],c[1]][n],z:[o[2],c[2]][r]})))))}
